-- 149_grammar_en_es_de_fr.sql
-- Грамматика для en/es/de/fr (conjugation/article/past/futuro). Итальянский НЕ трогаем.
-- Идемпотентно: CHECK + полная переустановка строк этих 4 языков.
ALTER TABLE public.grammar_items DROP CONSTRAINT IF EXISTS grammar_items_language_check;
ALTER TABLE public.grammar_items ADD  CONSTRAINT grammar_items_language_check CHECK (language IN ('en','it','es','de','fr'));
DELETE FROM public.grammar_items WHERE language IN ('en','es','de','fr');

